// ─── File: src/main/java/com/bank/resolution/service/AccountResolutionService.java ───
package com.bank.resolution.service;

import com.bank.resolution.dto.ResolutionReport;
import com.bank.resolution.model.Account;
import lombok.extern.slf4j.Slf4j;
import org.springframework.stereotype.Service;
import java.math.BigDecimal;
import java.util.*;

@Service
@Slf4j
public class AccountResolutionService {

    // Simulated multi-system lookups — each returns Optional
    private Optional<Account> findInSavings(String holderName) {
        log.info("  Searching SAVINGS for {}", holderName);
        if ("Rajesh Kumar".equals(holderName)) {
            return Optional.of(new Account("SAV2001", holderName, "SAVINGS", new BigDecimal("125000.50")));
        }
        return Optional.empty();
    }

    private Optional<Account> findInCurrent(String holderName) {
        log.info("  Searching CURRENT for {}", holderName);
        if ("Rajesh Kumar".equals(holderName)) {
            return Optional.of(new Account("CUR3001", holderName, "CURRENT", new BigDecimal("850000")));
        }
        return Optional.empty();
    }

    private Optional<Account> findInNRI(String holderName) {
        log.info("  Searching NRI for {}", holderName);
        return Optional.empty();  // nobody found in NRI for this demo
    }

    // Simulated parser — returns Optional (might fail)
    private Optional<BigDecimal> tryParseAmount(String raw) {
        try {
            return Optional.of(new BigDecimal(raw));
        } catch (NumberFormatException e) {
            return Optional.empty();  // parse failed — empty
        }
    }

    public ResolutionReport resolve(String holderName) {
        List<String> improvements = new ArrayList<>();

        // ═══ 1. Optional.or() — lazy fallback chain ═══
        // Try savings → if empty, try current → if empty, try NRI
        Optional<Account> resolved = findInSavings(holderName)
            .or(() -> findInCurrent(holderName))   // LAZY: only called if savings is empty
            .or(() -> findInNRI(holderName));       // LAZY: only called if both above are empty

        String resolvedAccount = resolved
            .map(a -> a.accountId() + " [" + a.accountType() + "] Rs." + a.balance())
            .orElse("NOT FOUND in any system");

        // For Rajesh: findInSavings returns present → or() suppliers NEVER called!
        // For unknown: findInSavings empty → findInCurrent called → empty → findInNRI called → empty
        improvements.add("or(): findInSavings.or(findInCurrent).or(findInNRI) — lazy fallback chain");

        // ═══ 2. Optional.stream() — drop empties with flatMap ═══
        List<String> rawAmounts = List.of("245050", "bad_data", "176000", "not_a_number", "330150");

        // BEFORE Java 9: verbose
        List<BigDecimal> beforeJ9 = rawAmounts.stream()
            .map(this::tryParseAmount)
            .filter(Optional::isPresent)
            .map(Optional::get)
            .toList();

        // AFTER Java 9: clean
        List<BigDecimal> afterJ9 = rawAmounts.stream()
            .map(this::tryParseAmount)           // Stream<Optional<BigDecimal>>
            .flatMap(Optional::stream)            // present → value, empty → gone
            .toList();

        List<String> parsedDisplay = afterJ9.stream()
            .map(a -> "Rs." + a.toPlainString())
            .toList();
        improvements.add("stream(): flatMap(Optional::stream) replaces filter(isPresent).map(get)");

        // ═══ 3. Optional.ifPresentOrElse() — handle both cases ═══
        StringBuilder notifResult = new StringBuilder();

        resolved.ifPresentOrElse(
            account -> {
                notifResult.append("✅ Confirmation sent to ").append(account.holderName())
                    .append(" for account ").append(account.accountId());
                log.info("Notification sent for {}", account.accountId());
            },
            () -> {
                notifResult.append("⚠ Alert: No account found for ").append(holderName);
                log.warn("No account found — alert triggered for {}", holderName);
            }
        );
        improvements.add("ifPresentOrElse(): present→send confirmation, empty→log alert");

        return new ResolutionReport(resolvedAccount, "savings → current → NRI",
            parsedDisplay, notifResult.toString(), improvements);
    }
}
