// ─── File: src/test/java/com/bank/resolution/service/OptionalJava9Test.java ───
package com.bank.resolution.service;

import org.junit.jupiter.api.Test;
import java.math.BigDecimal;
import java.util.*;
import java.util.concurrent.atomic.AtomicBoolean;
import java.util.stream.Stream;
import static org.assertj.core.api.Assertions.*;

class OptionalJava9Test {

    // ═══ Optional.stream() ═══
    @Test
    void streamPresent() {
        List<String> result = Optional.of("RELIANCE").stream().toList();
        assertThat(result).containsExactly("RELIANCE");
    }

    @Test
    void streamEmpty() {
        List<String> result = Optional.<String>empty().stream().toList();
        assertThat(result).isEmpty();
    }

    @Test
    void flatMapOptionalStreamDropsEmpties() {
        List<Optional<String>> opts = List.of(
            Optional.of("A"), Optional.empty(), Optional.of("B"), Optional.empty());

        // BEFORE: filter + get
        List<String> before = opts.stream().filter(Optional::isPresent).map(Optional::get).toList();

        // AFTER: flatMap(Optional::stream)
        List<String> after = opts.stream().flatMap(Optional::stream).toList();

        assertThat(before).containsExactly("A", "B");
        assertThat(after).containsExactly("A", "B");  // same result, cleaner!
    }

    // ═══ Optional.or() ═══
    @Test
    void orReturnsFirstPresentOptional() {
        Optional<String> result = Optional.<String>empty()
            .or(() -> Optional.of("FALLBACK"));
        assertThat(result).contains("FALLBACK");
    }

    @Test
    void orIsLazy() {
        AtomicBoolean supplierCalled = new AtomicBoolean(false);
        Optional<String> result = Optional.of("PRIMARY")
            .or(() -> { supplierCalled.set(true); return Optional.of("FALLBACK"); });

        assertThat(result).contains("PRIMARY");
        assertThat(supplierCalled.get()).isFalse();  // supplier NEVER called — lazy!
    }

    @Test
    void orChainsMultipleFallbacks() {
        Optional<String> result = Optional.<String>empty()
            .or(() -> Optional.empty())                    // first fallback: also empty
            .or(() -> Optional.of("THIRD_FALLBACK"));      // second fallback: present!

        assertThat(result).contains("THIRD_FALLBACK");
    }

    // ═══ Optional.ifPresentOrElse() ═══
    @Test
    void ifPresentOrElseExecutesPresentAction() {
        StringBuilder log = new StringBuilder();
        Optional.of("RELIANCE").ifPresentOrElse(
            v -> log.append("Found: ").append(v),
            () -> log.append("Not found"));
        assertThat(log.toString()).isEqualTo("Found: RELIANCE");
    }

    @Test
    void ifPresentOrElseExecutesEmptyAction() {
        StringBuilder log = new StringBuilder();
        Optional.empty().ifPresentOrElse(
            v -> log.append("Found: ").append(v),
            () -> log.append("Not found"));
        assertThat(log.toString()).isEqualTo("Not found");
    }

    // ═══ Real use case: tryParse + flatMap(Optional::stream) ═══
    @Test
    void tryParseWithOptionalStream() {
        List<BigDecimal> parsed = Stream.of("100", "bad", "200", "oops", "300")
            .map(s -> { try { return Optional.of(new BigDecimal(s)); }
                        catch (Exception e) { return Optional.<BigDecimal>empty(); } })
            .flatMap(Optional::stream)
            .toList();

        assertThat(parsed).containsExactly(
            new BigDecimal("100"), new BigDecimal("200"), new BigDecimal("300"));
        // "bad" and "oops" silently dropped — no exception propagation!
    }
}
